function OverseaClubBossRankClubNode:FillSv()
    local count = table.count(self.data.rankInfo)
    if not self.ClubRankSv.IsListViewInit then
        self.ClubRankSv:InitListView(count, Bind(self, self.OnRefreshCellIndex))
        self.ClubRankSv:UpdateDisplayItemCount(ItemCell)
    else
        GameUtils.ReloadData(self.ClubRankSv, count)
    end
    self.ClubRankSv:MovePanelToItemIndex(0,0)
end

function OverseaClubBossRankClubNode:OnRefreshCellIndex(listView,index)
    local count = table.count(self.data.rankInfo)
    if index < 0 or index >= count then
        return
    end
    local cell = listView:NewListViewItem(ItemCell)
    local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
    if not isNull(tableCellEnv) then
        tableCellEnv:Refresh(self.data.rankInfo[index + 1])
        if listView.DisplayItemNumber < listView.DisplayItemCount then
            tableCellEnv:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            tableCellEnv:PlayAnimByIdle()
        end
    end
    return cell
end

function OverseaClubBossRankClubNode:FillInfo()
    local data = self:GetRankData()
    self.cardDisplayEnv:Refresh(data)
    self:RefreshReward()
    self:SetTitleStatus(self.isCurrent)
    self:SetRewardTipsShow(self.isCurrent)
    local clubHomeDojo = ClubUtils.GetClubComp():GetHomeDojo()
    CfUtils.FillText(self.ClubName,clubHomeDojo.name)
    CfUtils.FillText(self.ClubDamage,self.data.myRank.score)
end

function OverseaClubBossRankClubNode:SetRewardTipsShow(isCurrent)
    KTool.SetActive(self.RewardReceiveTips.gameObject,isCurrent)
    if isCurrent then
        local bossDojo = ClubUtils.GetClubComp():GetBossDojo()
        local times = 0
        if not isNull(bossDojo) then
            times = bossDojo:GetParticipateTimes()
        end
        local needCount = ClubUtils.GetParamValue(ClubUtils.ParamsId.BOSS_CHALLENGE_REWARD_TIMES)
        CfUtils.FillText(self.TextDesc2,localize("领取排名奖励需在该社团参与特训_Time1_次（_Time2_/_Time3_)",{_Time1_ = needCount,_Time2_ = times,_Time3_ = needCount}))
    end
end

function OverseaClubBossRankClubNode:RefreshReward()
    if self.rewardNodeEnv == nil then
        return
    end
    
    if self.data.myRank.ranking == 0 then
        self.rewardNodeEnv:Refresh({},false)
    else
        local percentRank = checkNumber(self.data.percentageRank)
        local type = percentRank == 0 and 1 or 2
        local _rank = percentRank == 0 and self.data.myRank.ranking or percentRank
        local reward = ClubUtils.GetRankReward(type,_rank) or {}
        self.rewardNodeEnv:Refresh(reward,true)
    end
end


function OverseaClubBossRankClubNode:GetRankData()
    local clubHomeDojo = ClubUtils.GetClubComp():GetHomeDojo()
    local clubHeadVo = ClubUtils.GetClubHeadVo(clubHomeDojo.avatar)
    local rank = self.data.myRank.ranking
    local data = {photoPath = clubHeadVo.photoPath,rank = rank}
    return data
end

function OverseaClubBossRankClubNode:OnFontStyleButtonClick()
    self.isCurrent = not self.isCurrent
    if self.callBack then
        self.callBack(self.isCurrent)
    end
end

function OverseaClubBossRankClubNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

